def set_global_seed(seed: int) -> None:
    if not isinstance(seed, int) or seed < 0:
        raise ValueError(f"seed must be a nonnegative int, got: {seed!r}")

    random.seed(seed)
    np.random.seed(seed)

    if TORCH_AVAILABLE:
        torch.manual_seed(seed)  # type: ignore[attr-defined]
        if hasattr(torch, "cuda") and torch.cuda.is_available():  # type: ignore[union-attr]
            torch.cuda.manual_seed_all(seed)  # type: ignore[union-attr]

        try:
            if hasattr(torch, "backends") and hasattr(torch.backends, "cudnn"):  # type: ignore[union-attr]
                torch.backends.cudnn.deterministic = True  # type: ignore[union-attr]
                torch.backends.cudnn.benchmark = False  # type: ignore[union-attr]
        except Exception:
            pass

        try:
            torch.use_deterministic_algorithms(True)  # type: ignore[union-attr]
        except Exception:
            pass


